EXEGESIS[25] = [
    ("25:1–3", "태형은 사십 대를 넘기지 말라", [
        ("C T", "크레이기는 율법 연설의 앞부분에서 새 아내의 처녀성에 관해 거짓 고소를 한 남자가 배상금을 물고 체벌도 받았다는 점을 상기시키며(22:18), 이 단락이 법정의 태형 절차를 규정한다고 설명한다. 사람들 사이에 시비가 생겨 재판을 청하면 재판장은 의인은 의롭다 하고 악인은 정죄할 것이다(25:1). 악인에게 태형이 합당하면 재판장은 그를 엎드리게 하고 자기 앞에서 그의 죄에 따라 수를 맞추어 때리게 하되, 사십까지는 때리려니와 그것을 넘기지는 못한다. 만일 그것을 넘겨 매를 지나치게 때리면 네가 네 형제를 경히 여기는 것이 될까 하노라(25:2–3). 톰슨은 중세 앗시리아 법이 사십 대(A18)나 오십 대(A19)의 태형을 규정한 것과 비교하고, 바울이 사십에서 하나 감한 매를 다섯 번 맞았다는 고린도후서 11:24와 이 관행을 규정한 미쉬나 마코트의 대목을 든다. 처벌받는 사람도 여전히 형제다."),
    ]),
    ("25:4", "곡식 떠는 소에게 망을 씌우지 말라", [
        ("C", "곡식 떠는 소에게 망을 씌우지 말지니라. 크레이기는 이 짧은 법이 오경의 다른 법에 정확한 평행이 없고 바로 앞뒤의 문맥과 특별한 관계도 없어 보인다고 설명한다. 그는 이 법이 짐승에 대한 관심을 표현하며, 안식일 계명(5:14)에 담긴 일반적인 관심에서 나왔을 수 있다고 본다. 바울은 이 말씀을 인용해 복음을 전하는 자가 그 일로 생활비를 얻는 것이 마땅하다고 논증했다(고전 9:9; 딤전 5:18)."),
    ]),
    ("25:5–6", "형사취수의 법", [
        ("C T", "크레이기는 형사취수에 관한 법이 신명기의 율법 제시에만 있지만 그 관습은 오래되었고(창 38장) 여기서 이스라엘 언약 공동체의 법적 권위를 얻는다고 설명한다. 법의 내용은 죽은 형제의 아들 없는 과부를 남자가 아내로 맞아 책임지는 것이며, 특정한 조건에서만 적용되었다. 형제들이 함께 사는데 그중 하나가 아들 없이 죽으면(25:5), 그 과부는 나가서 타인에게 시집가지 말고 남편의 형제가 그에게로 들어가서 아내로 맞이하여 남편의 형제 된 의무를 행한다. 그 여인이 낳은 첫 아들이 죽은 형제의 이름을 잇게 하여 그 이름이 이스라엘 중에서 끊어지지 않게 한다(25:6). 톰슨은 이 관습의 이름이 라틴어 <em>레비르</em>(남편의 형제)에서 왔다고 설명하고, 헷 족속과 앗시리아, 그리고 인도와 아프리카와 남아메리카 같은 여러 지역에서도 알려졌으며, 앗시리아에서는 약혼한 경우까지 확대되었다고 말한다."),
    ]),
    ("25:7–10", "신 벗김 받은 자의 집", [
        ("C T", "크레이기는 남편의 형제에게 과부에 대한 의무를 거절할 법적 권리가 있었지만, 그 권리를 행사하면 공동체의 강한 비난을 받았다고 설명한다. 그 사람이 형제의 아내를 맞이하기를 즐겨하지 아니하면 그 형제의 아내는 그 성문으로 장로들에게로 나아가서 호소하고(25:7), 성읍 장로들은 그를 불러다가 말한다(25:8). 그래도 거절하면 여인이 장로들 앞에서 그에게 나아가서 그의 발에서 신을 벗기고 그의 얼굴에 침을 뱉으며, 그 형제의 집을 세우기를 즐겨하지 아니하는 자에게는 이같이 할 것이라고 선언한다(25:9). 이스라엘 중에서 그의 이름은 ‘신 벗김 받은 자의 집’이라 불린다(25:10). 톰슨은 이 의무를 피할 길이 마련되어 있었지만 그 선택이 권장되지 않았다고 보고, 그 법적 절차가 성문의 장로들 앞에서 이루어졌다고 설명한다. 룻기 4장에서 기업 무를 친족이 신을 벗어 그 권리를 넘기는 장면은 관련된 관습을 보여 준다."),
    ]),
    ("25:11–12", "싸움에 끼어든 아내의 손", [
        ("C T", "두 사람이 서로 싸우는데 한 사람의 아내가 그 치는 자의 손에서 남편을 구하려고 손을 벌려 그 사람의 음낭을 잡으면 그 여인의 손을 찍어 버리고 불쌍히 보지 말라. 크레이기는 싸우는 두 사람이 모두 이스라엘 사람(‘형제’)이라는 점을 짚고, 이 법이 오경에서 여기에만 나온다고 설명한다. 그는 이 법이 일반적으로 목적이 수단을 정당화하지 않는다는 원리를 보여 준다고 본다. 그는 이 처벌이 동해 보복법(19:21)의 연장이며, 사건에 관련된 사람들의 성이 달라 동해 보복을 문자 그대로 적용할 수 없었다고 설명한다. 톰슨은 싸움에 끼어든 여인의 극단적인 무례를 짧게 다루는 이 법에 여러 특이한 점이 있다고 지적한다."),
    ]),
    ("25:13–16", "온전하고 공정한 저울추와 되", [
        ("C T", "크레이기는 평행 규정으로 레위기 19:35–37을 들고, 비슷한 훈계가 근동 문헌에도 알려져 있다고 설명한다. 재판에 가장 높은 도덕 기준이 요구되었듯(16:18–20) 상거래에도 엄격한 윤리 원칙이 요구되었고, 두 경우 모두 그 결과는 약속의 땅에서의 장수였다(25:15; 16:20 참조). 상인이 손님을 착취하는 거짓 저울추와 되(암 8:5 참조)는 금지된다. 크레이기는 상인이 살 때에는 큰 저울추(문자적으로 ‘돌’)나 큰 되(<em>에파</em>)로 값보다 많이 얻고, 팔 때에는 작은 것으로 덜 주었다고 설명한다. 너는 네 주머니에 두 종류의 저울추 곧 큰 것과 작은 것을 넣지 말 것이며, 네 집에 두 종류의 되 곧 큰 것과 작은 것을 두지 말 것이다(25:13–14). 톰슨은 두 금지 조항이 고대 근동의 전통적인 관습법과 이어지는 고리가 된다고 보고, 이스라엘에서는 언약 백성 모두에게 상거래의 엄격한 정직이 요구되었다고 설명한다. 이런 일을 행하는 모든 자는 여호와께 가증하다(25:16)."),
    ]),
    ("25:17–19", "아말렉이 네게 행한 일을 기억하라", [
        ("C T", "너희가 애굽에서 나오는 길에 아말렉이 네게 행한 일을 기억하라(25:17). 크레이기는 출애굽기 17:8–16이 르비딤에서 이스라엘과 아말렉 사이의 한 특정한 충돌을 서술하지만, 이 절들은 여러 차례의 충돌을 염두에 두었을 것이며 르비딤의 일은 그 가운데 하나라고 설명한다. 아말렉은 네가 피곤할 때에 길에서 너를 만나 네 뒤에 떨어진 약한 자들을 쳤고 하나님을 두려워하지 아니하였다(25:18). 크레이기는 율법 제시가 끝나 가는 대목에 놓인 이 짧은 단락이 처음에는 문맥에서 벗어난 듯 보이며, 총회에 들어오는 문제를 다룬 앞의 외국 민족 규정(23:3–8)과도 내용상 연결되지 않는다고 인정한다. 톰슨은 이 단락이 신명기의 다른 법 조문과 표현이 다르면서도 마지막에 필연법 형식의 명령이 주어진다고 설명한다. 여호와께서 사방의 적군으로부터 안식을 주실 때에 너는 천하에서 아말렉에 대한 기억을 지워 버리고 잊지 말라(25:19). 사무엘상 15장은 이 명령과 사울의 실패를 이야기한다."),
    ]),
]

EXEGESIS[26] = [
    ("26:1–2", "땅에 들어가 처음 거둔 열매를 광주리에", [
        ("C T", "크레이기는 세부 법규(12–26장)의 주된 내용이 약속의 땅에서 이어질 미래의 삶을 내다보는 데 비해, 26:1–15는 이스라엘이 땅을 차지하고 그 소산으로 살기 시작하자마자 거행할 두 가지 특별한 의식을 다룬다고 설명한다. 서로 다른 때와 장소에서 열릴 이 의식들은 땅의 첫 열매를 처음으로 드리는 일(26:1–11)과 셋째 해 십일조를 처음으로 거행하는 일(26:12–15)이다. 첫째 의식은 약속의 땅에 들어가(‘네가 들어가서’) 정복을 마치고(‘차지하여’) 그 땅에 살며 소산으로 살아가기 시작했을 때(‘거기에 거주할 때에’) 거행된다(26:1). 백성은 성소에서 가져온 첫 열매의 일부를 광주리에 담았다(26:2). 크레이기는 광주리의 부분이 가져온 전체를 상징했다고 설명하고, 톰슨은 히브리어 전치사 <em>민</em>이 부분을 나타내므로 견본만 가져갔으며, 그것이 땅의 모든 소산의 첫 열매였으므로 널리 분포된 견본이었으리라고 추론한다."),
    ]),
    ("26:3–4", "그 때의 제사장에게 아뢰는 말", [
        ("C T", "예배자는 그 때의 제사장에게 나아가 ‘내가 오늘 당신의 하나님 여호와께 아뢰나이다 내가 여호와께서 우리에게 주시겠다고 우리 조상들에게 맹세하신 땅에 이르렀나이다’라고 말한다(26:3). 톰슨은 ‘그 때의 제사장’을 중앙 성소의 대제사장으로 보고, 실로의 엘리가 ‘제사장’으로 불린 예(삼상 1:9; 2:13–16)를 든다. 제사장은 그 손에서 광주리를 받아 여호와의 제단 앞에 놓는다(26:4). 크레이기는 서술이 매우 간결해서 나머지 의식의 절차를 확정하기 어렵다고 인정한다. 톰슨은 26:4가 26:5–10의 고백보다 앞에 놓여 생기는 순서의 문제를 두고, 26:3–4를 설명의 주석으로 보면 제물을 드리면서 고백을 했다고 보는 것이 합리적이라고 설명한다."),
    ]),
    ("26:5", "내 조상은 방랑하는 아람 사람으로서", [
        ("C T", "예배자가 할 말은 최근 구약 학계에서 큰 논쟁의 대상이 되었다. 크레이기와 톰슨은 폰 라트의 주장을 소개한다. 폰 라트는 이 구절들이 신조의 모든 특징을 지니며 구약에서 알아볼 수 있는 가장 이른 신조일 수 있다고 보았고, 톰슨은 이 고백과 비슷한 본문들에 시내산 언급이 없다는 사실이 폰 라트로 하여금 이스라엘 신앙 고백의 가장 오래된 형태에 시내산이 없었다고 제안하게 했다고 설명한다. 크레이기는 ‘방랑하는 아람 사람’을 ‘병든’ 또는 ‘죽어 가는’ 아람 사람으로 읽고, 아들들과 함께 애굽에 들어간 야곱을 가리킨다고 설명한다. 야곱은 애굽에 내려갈 때 이미 백삼십 세의 노인이었고(창 47:9) 죽음을 앞두고 있었다(창 45:28; 46:30). 톰슨은 생존의 가능성이 그토록 희박해 보였던 그에게서 큰 민족이 나왔다고 설명한다. 그는 칠십 명의 소수로(출 1:5) 애굽에 내려가 거류하는 나그네(<em>게르</em>)로 살았고, 거기서 크고 강하고 번성한 민족이 되었다."),
    ]),
    ("26:6–9", "우리의 고통과 수고와 압제를 보시고", [
        ("C T", "크레이기는 이 고백이 가나안 땅의 야곱에서 시작해 애굽으로의 이주를 서술하고, 둘째 부분(26:6–8)이 애굽에서 시작해 큰 출애굽을 서술한다고 정리한다. 애굽 사람이 우리를 학대하며 우리를 괴롭히며 우리에게 중노동을 시켰다(26:6). 톰슨은 애굽의 압제와 그 가혹한 노동이 전체 주제의 중요한 요소였다고 설명한다. 여호와께서 바로 그런 처지에서 백성을 건지셨기 때문이다(출 1:14). 우리가 우리 조상들의 하나님 여호와께 부르짖었더니 여호와께서 우리 음성을 들으시고 우리의 고통과 신고와 압제를 보시고(26:7), 강한 손과 편 팔과 큰 위엄과 이적과 기사로 우리를 애굽에서 인도하여 내셨다(26:8). 톰슨은 여호와의 구원이 흔히 이런 힘찬 표현으로 묘사된다고 설명한다. 이곳으로 인도하사 이 땅 곧 젖과 꿀이 흐르는 땅을 우리에게 주셨다(26:9)."),
    ]),
    ("26:10–11", "이제 내가 맏물을 가져왔나이다", [
        ("C T", "크레이기는 고백의 절정이 26:10 전반에 있다고 본다. 하나님이 백성을 땅으로 이끄시려고 움직이셨던 모든 일을 기억하며, 그 땅의 첫 참된 거주자 세대가 주어진 땅의 열매를 예물로 드리며 하나님께 돌아온다. 여호와여 이제 내가 주께서 내게 주신 토지 소산의 맏물을 가져왔나이다. 그것을 여호와 앞에 두고 경배한다. 톰슨은 ‘경배하다’의 어근 <em>ḥ-w-y</em>가 히브리어와 가나안어 모두에서 ‘엎드리다’를 뜻한다고 설명한다. 여호와께서 너와 네 집에 주신 모든 복으로 말미암아 너는 레위인과 너희 가운데에 거류하는 객과 함께 즐거워할지니라(26:11). 톰슨은 여호와를 향한 예배의 즐거운 음조를 강조하고(12:6–7, 11–12, 17–18; 16:11, 14), 한 사람의 가족이 레위인과 거류하는 나그네와 함께 하나님이 주신 좋은 것을 즐거워한다는 사실이 일종의 공동체적 유대를 시사한다고 설명한다."),
    ]),
    ("26:12–13", "셋째 해 십일조를 나눈 뒤의 선언", [
        ("C T", "크레이기는 첫 열매를 처음 드리는 일이 온전히 정착한 첫해에 있었다면, 26:12–15의 의식은 두 해 뒤, 곧 정착한 셋째 해에 있었을 것이라고 설명한다. 셋째 해 곧 십일조를 드리는 해에 모든 소산의 십일조를 레위인과 객과 고아와 과부에게 주어 성읍 안에서 먹고 배부르게 한다(26:12). 톰슨은 사회의 약자들이 이 십일조의 혜택을 받았다고 설명하고, 이 분배가 중앙 성소에서 여호와 앞에서 행하는 의식이 아니었으므로 이스라엘 사람이 성소에 가서 의무를 이행했다고 선언하도록 되어 있었다고 본다. 크레이기는 선언을 세 부분으로 정리한다. 긍정적 진술에서 예배자는 셋째 해 십일조의 법을 이행했다고 선언하고, 그 진술은 명령을 범하지도 잊지도 않았다는 두 부정의 구절로 완전한 이행을 강조한다(26:13)."),
    ]),
    ("26:14–15", "애곡하는 날에 먹지 않았고, 하늘에서 보시고 복을 내리소서", [
        ("C T", "선언의 둘째 부분은 부정적 진술이다(26:14). 톰슨은 예배자가 세 가지 특정한 관행에 관여하지 않았다고 밝힌다고 설명한다. 애곡하는 날에 이 성물을 먹지 않았고, 부정한 몸으로 이를 떼어 두지 않았고, 죽은 자를 위하여 이를 쓰지 않았다. 셋째 부분은 기도다(26:15). 원하건대 주의 거룩한 처소 하늘에서 보시고 주의 백성 이스라엘에게 복을 주시며 우리 조상들에게 맹세하여 우리에게 주신 젖과 꿀이 흐르는 땅에 복을 내리소서. 크레이기는 이 기도가 집이나 정착지에서 드려졌기 때문에 여호와께서 택하실 곳을 언급하지 않고 하늘에 계신 하나님께 향했을 것이라고 본다. 톰슨은 하늘 처소에서 굽어보시는 하나님께 드리는 기도를 열왕기상 8:30, 역대하 30:27, 예레미야 25:30, 스가랴 2:13과 연결한다."),
    ]),
    ("26:16", "마음을 다하고 뜻을 다하여 지켜 행하라", [
        ("C T", "크레이기는 이 짧은 단락이 율법에 관한 연설, 더 정확히는 세부 법규에 관한 연설의 결론이라고 설명하고, 세부 법규의 짧은 서론(12:1)이 26:16에 반영되어 있다고 본다. 오늘 네 하나님 여호와께서 이 규례와 법도를 행하라고 네게 명령하시나니 그런즉 너는 마음을 다하며 뜻을 다하여 지켜 행하라. 톰슨은 이 절이 5–26장의 의무 전체에 대한 권면의 결론이며, 규례와 법도(<em>미쉬파팀</em>)를 온 마음과 온 뜻으로, 곧 전심으로 행하라는 명령이라고 설명한다."),
    ]),
    ("26:17–19", "서로를 인정하는 언약의 말", [
        ("C T", "크레이기는 26:17–19가 언약 갱신 의식의 한 부분과 관련되며, 의식 자체가 명시되지 않았지만 모세의 말이 그 성격을 알려 준다고 설명한다. ‘오늘’(26:17, 18)은 모압 평지에서 율법 연설이 선포된 때다. ‘인정하다’로 옮겨진 동사에 대해 크레이기는 공식적인 헌신의 선언을 가리키며 조약과 언약의 전문 용어일 수 있다고 설명한다. 톰슨은 이 동사가 사역형으로 문자적으로 ‘(여호와로 하여금) 말하게 하였다’를 뜻한다고 설명하고, 언약의 두 당사자가 서로 협약의 조건을 낭독하게 한 세속 조약의 평행을 제시한다. 네가 오늘 여호와를 네 하나님으로 인정하고 그 도를 행하겠다고 했으며(26:17), 여호와께서도 네게 말씀하신 대로 너를 그의 보배로운 백성이 되게 하셨다(26:18). 톰슨은 같은 동사가 여기서도 쓰여, 여호와께서 이스라엘로 하여금 그의 백성이라고 선언하게 하셨고 그것은 여호와 자신이 그 사실을 받아들여 ‘너는 내 백성이라’고 확언하실 수 있다는 뜻이라고 설명한다. 여호와께서 너를 찬송과 명예와 영광에 있어서 모든 민족 위에 뛰어나게 하시고 너를 성민이 되게 하신다(26:19)."),
    ]),
]

EXEGESIS[27] = [
    ("27:1", "모세와 이스라엘 장로들이 명령하다", [
        ("C T", "크레이기는 세부 법규의 본문(12–26장)이 미래의 언약 갱신을 내다보는 두 단락, 곧 11:26–32와 27:1–26 사이에 끼어 있다고 설명한다. 모세와 이스라엘 장로들이 백성에게 명령한다는 짝지음은 이례적이다. 신명기에서 모세는 보통 혼자 백성에게 말한다. 톰슨은 신명기의 ‘법’ 단락에서 모세를 직접 언급하는 일이 드물며(4:44–45; 5:1 참조), 이 절이 5:1처럼 중요한 단락을 연다고 설명한다. 그는 27:1–8의 요구를 26:16–19의 백성의 응답 뒤에 오는 마지막 언약 조항으로 보아 27장이 28장 앞에 자연스럽게 놓인다는 웬함의 제안을 소개한다. 크레이기는 이어지는 지침이 율법을 기록할 돌을 준비하는 일과 제사를 드릴 제단을 쌓는 일이라는 두 의식을 다룬다고 설명한다."),
    ]),
    ("27:2–4", "석회를 바른 큰 돌들과 에발 산", [
        ("C T", "요단을 건너는 날에 큰 돌들을 세우고 석회를 발라 그 위에 이 율법의 모든 말씀을 기록한다(27:2–3). 크레이기는 돌을 세운 뒤 석회를 칠해 글쓰기에 알맞게 준비했고, 율법을 쓰면 흰 바탕 덕분에 글이 분명히 보이고 쉽게 읽혔다고 설명한다. 그 돌들은 에발 산에 세우라는 명령이 주어진다(27:4). 크레이기는 에발 산과 그리심 산이 요단 서편, 예루살렘에서 북쪽으로 약 40마일 되는 곳에 있었다고 설명한다. 톰슨은 요단 건넘이 아직 미래로 그려지며 그날의 언약 갱신 의식에 관한 여러 구체적인 지침이 주어진다고 보고, 27:3과 27:8의 반복을 히브리 저술 방식으로 설명하며 별도의 옛 조각의 시작일 수 있다고 본다."),
    ]),
    ("27:5–7", "다듬지 않은 돌의 제단과 번제와 화목제", [
        ("C T", "크레이기는 돌을 세우는 일과 함께 다듬지 않은 온전한 돌로 제단을 쌓으라는 명령이 시내산에서 이미 주어진 지침(출 20:25)을 따른다고 설명한다. 톰슨은 에발 산에 제단을 쌓는 일이 12장의 중앙 성소 문제를 제기한다고 인정하고, 중앙 성소가 있던 때에도 다른 곳의 정당한 제단이 있었다는 성경 기록의 사실을 들어 이 문제를 논한다. 그는 이 둘째 단계가 언약 비준 의식의 제사와 관련된다고 보고 출애굽기 24:1–8과 비교한다. 두 종류의 제물이 언급된다(27:6–7). 톰슨은 번제(<em>올라</em>)는 불에 완전히 태워져 여호와께 드려졌고, 화목제(<em>셸라밈</em>)는 나누어 먹었다고 설명한다. 거기서 먹으며 네 하나님 여호와 앞에서 즐거워하라(27:7)."),
    ]),
    ("27:8", "율법의 모든 말씀을 매우 명백하게 기록하라", [
        ("C T", "너는 그 돌들 위에 이 율법의 모든 말씀을 매우 명백하게 기록할지니라. 톰슨은 ‘매우 명백하게’가 문자적으로 ‘잘 새겨’이며, 문법적으로 두 부정사를 부사적으로 겹쳐 쓴 강한 표현이라고 설명한다. 크레이기는 1:5에서 모세가 율법을 ‘설명하기’ 시작했다고 할 때 쓰인 동사(<em>베에르</em>)가 여기서 글씨의 분명함과 읽기 쉬움을 가리킨다고 짚는다."),
    ]),
    ("27:9–10", "오늘 네가 여호와의 백성이 되었으니", [
        ("C", "크레이기는 27:1처럼 온 이스라엘이 다시 하나님의 말씀을 듣고 순종하라는 권면을 받는다고 설명한다. 이스라엘아 잠잠하여 들으라 오늘 네가 네 하나님 여호와의 백성이 되었으니(27:9; 26:16–19 참조). 크레이기는 그 뜻이 언약 갱신에서 이스라엘이 하나님의 백성이라는 신분을 새롭게 했다는 것이라고 설명한다. 그러므로 네 하나님 여호와의 말씀을 청종하여 오늘 명령하는 그 명령과 규례를 행하라(27:10)."),
    ]),
    ("27:11–14", "그리심 산과 에발 산에 선 지파들", [
        ("C T", "크레이기는 이 절들이 세겜 부근에서 열릴 언약 갱신에서의 축복과 저주 의식의 장면을 설정한다고 설명한다(11:26–32 참조). 백성을 축복하기 위해 그리심 산에 설 지파는 시므온과 레위와 유다와 잇사갈과 요셉과 베냐민이다(27:12). 톰슨은 이 여섯 지파가 야곱의 아내 레아와 라헬의 자손이며, 큰길이 북쪽으로 지나는 두 봉우리 가운데 남쪽 산에 서서 백성을 축복했다고 설명한다. 저주하기 위해 에발 산에 설 지파는 르우벤과 갓과 아셀과 스불론과 단과 납달리다(27:13). 레위 사람은 큰 소리로 이스라엘 모든 사람에게 선포한다(27:14)."),
    ]),
    ("27:15", "첫째 저주와 아멘", [
        ("C T", "27:15–26에 열두 저주, 곧 크레이기가 부르는 ‘열두 조항’이 이어진다. 각 저주에 모든 백성은 ‘아멘’으로 답한다. 크레이기는 이 낱말이 바로 앞에 선포된 말을 가리키며 그 말에 동의하고 받아들인다는 뜻이라고 설명한다. 톰슨은 열두 공식이 모두 ‘저주를 받을 것이라’(<em>아루르</em>)로 시작하며, 이 무리에 속한 백성이 열두 지파 전체를 대표해 아멘으로 답했다고 설명한다. 첫째 저주는 장색의 손으로 조각하였거나 부어 만든 우상을 은밀히 세우는 자에게 내린다. 크레이기는 그 범죄가 다른 신의 우상이라면 첫째 계명을, 여호와를 형상으로 나타내려는 시도라면 둘째 계명을 어기는 일이라고 설명한다."),
    ]),
    ("27:16–19", "부모를 경홀히 여기는 자, 경계표를 옮기는 자, 맹인과 약자를 속이는 자", [
        ("C T", "둘째 저주는 부모를 경홀히 여기는 자에게 내린다(27:16). 크레이기는 이것이 다섯째 계명을 행동으로 어기는 일이라고 설명한다. 톰슨은 21:18–21, 출애굽기 21:15, 레위기 20:9, 에스겔 22:7을 함께 들고, ‘경홀히 여기다’의 어근 <em>q-l-l</em>이 ‘가볍다, 작다, 멸시받다’를 뜻한다고 설명한다. 셋째 저주는 다른 사람에게 정당하게 속한 땅을 얻으려고 이웃의 경계표를 옮기는 자에게 내린다(27:17; 19:14 참조). 톰슨은 경계표가 하나님이 나누어 주신 몫, 곧 기업의 경계를 정했으며 그것을 옮기는 일은 하나님이 정하신 것을 침범하는 일이었다고 설명한다. 넷째 저주는 맹인에게 길을 잃게 하는 자에게 내린다(27:18; 레 19:14). 크레이기는 이 말을 문자적으로 읽을 수도, 맹인을 이용해 이익을 얻는 행위를 가리키는 비유로 읽을 수도 있다고 본다. 다섯째 저주는 객과 고아와 과부의 송사를 억울하게 하는 자에게 내린다(27:19; 24:17). 크레이기는 이것이 쉽게 착취당할 수 있는 사회 구성원을 불의하게 이용하는 모든 자를 겨냥한다고 설명하고, 톰슨은 형편이 어려운 이들이 하나님의 특별한 돌보심 아래 있었다고 말한다."),
    ]),
    ("27:20–23", "은밀한 성범죄에 대한 네 저주", [
        ("C T", "크레이기는 이어지는 네 저주가 여러 형태의 성적 범죄를 겨냥하며, 이런 행위는 본래 은밀하게 행해지므로 법정에 드러나지 않는 경우가 많았다고 설명한다. 아버지의 아내와 동침하는 자(27:20), 짐승과 교합하는 자(27:21), 자매와 동침하는 자(27:22), 장모와 동침하는 자(27:23)다. 톰슨은 22:30, 레위기 18:8; 20:11, 함무라비 법전 158조를 비교하고, 레위기 18장과 20장이 이 금지들을 자세히 다룬다고 설명한다. 법정이 닿지 못하는 곳에서도 백성은 아멘으로 하나님의 판단을 받아들인다."),
    ]),
    ("27:24–25", "암살과 뇌물로 무죄한 자를 죽이는 일", [
        ("C", "크레이기는 열째와 열한째 저주가 살인이 저질러질 수 있는 여러 방식을 다루며, 여섯째 계명을 어기는 일이라고 설명한다. 그 이웃을 암살하는 자(27:24)는 은밀히 죽였으므로 재판에 넘겨지지 않을 수 있었다. 무죄한 자를 죽이려고 뇌물을 받는 자(27:25)는 직접 손을 대지 않고 살인에 가담한다. 두 경우 모두 법정의 눈을 피할 수 있는 범죄가 하나님의 저주 아래 놓인다."),
    ]),
    ("27:26", "이 율법의 말씀을 실행하지 아니하는 자", [
        ("C", "크레이기는 열두째 마지막 저주가 요약하며 모든 것을 포괄하는 성격을 지닌다고 설명한다. 이 율법의 말씀을 실행하지 아니하는 자는 저주를 받을 것이라. 이 저주는 율법에 대한 순종이 요구하는 적극적인 행동을 하지 않는 사람을 겨냥한다. 크레이기는 바울이 이 마지막 저주를 갈라디아서 3:10–14에서 해설한다고 설명한다. 율법의 요구가 삶의 모든 곳에 미치므로 사람은 ‘율법의 행위’에 근거해 하나님 앞에서 의롭다 함을 주장할 수 없다. 크레이기는 율법의 이 포괄적인 성격이 우리의 눈을 우리를 위하여 저주를 받은 바 되사 율법의 저주에서 우리를 속량하신 그리스도께로 돌리게 한다고 말한다(갈 3:13)."),
    ]),
]
